\set ON_ERROR_STOP on
begin;
create function pg_temp.assert_true(ok boolean, label text) returns void language plpgsql as $$ begin if ok is distinct from true then raise exception 'FAIL: %',label; end if; raise notice 'PASS: %',label; end $$;
create function pg_temp.denied(statement text, label text) returns void language plpgsql as $$
begin
 begin execute statement; exception when insufficient_privilege or check_violation or unique_violation or foreign_key_violation or raise_exception then raise notice 'PASS: %',label; return; end;
 raise exception 'FAIL: expected denial: %',label;
end $$;
set local role authenticated;
select set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000000001',true);
insert into public.cook_sessions(id,name,time_zone,revision,created_at) values ('10000000-0000-4000-8000-000000000001','A private cook','America/New_York',999,'1900-01-01');
select pg_temp.assert_true((select revision=1 and created_at>'1900-01-02'::timestamptz from public.cook_sessions),'client cannot forge creation metadata');
select pg_temp.assert_true((select owner_user_id=auth.uid() from public.cook_sessions),'ownership defaults to authenticated identity');
select pg_temp.denied($q$insert into public.cook_sessions(name,time_zone) values ('Duplicate','UTC')$q$,'only one open cook');
select pg_temp.denied($q$insert into public.cook_sessions(owner_user_id,name,time_zone) values ('00000000-0000-4000-8000-000000000002','Forged owner','UTC')$q$,'forged session ownership');
insert into public.cook_events(id,cook_id,task_id,event_type,occurred_at,payload,received_at) values ('20000000-0000-4000-8000-000000000001','10000000-0000-4000-8000-000000000001','step','temperature','2026-10-27T20:00:00Z','{"value":165}','1900-01-01');
select pg_temp.denied($q$update public.cook_events set payload='{}'$q$,'events cannot be rewritten');
select pg_temp.assert_true((select received_at>'1900-01-02'::timestamptz and occurred_at='2026-10-27T20:00:00Z'::timestamptz from public.cook_events),'server records event receipt time');
select pg_temp.denied($q$update public.cook_sessions set owner_user_id='00000000-0000-4000-8000-000000000002'$q$,'ownership cannot transfer on update');
select pg_temp.denied($q$insert into public.cook_events(cook_id,task_id,event_type,occurred_at,payload) values ('10000000-0000-4000-8000-000000000001','step','note',now(),'[]')$q$,'malformed event payload rejected');
select pg_temp.denied($q$delete from public.cook_events$q$,'events cannot be individually deleted');
select pg_temp.denied($q$insert into public.cook_events(cook_id,task_id,event_type,occurred_at,payload) values ('10000000-0000-4000-8000-000000000001','step','note',now(),jsonb_build_object('note',repeat('x',65536)))$q$,'oversized event payload rejected');
update public.cook_sessions set name='A edited',revision=999 where revision=1;
select pg_temp.assert_true((select revision=2 from public.cook_sessions),'server controls revisions');
with stale as (update public.cook_sessions set name='stale' where revision=1 returning id) select pg_temp.assert_true((select count(*)=0 from stale),'stale revision changes nothing');
select set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000000002',true);
select pg_temp.assert_true((select count(*)=0 from public.cook_sessions),'B cannot list A cooks');
select pg_temp.assert_true((select count(*)=0 from public.cook_events),'B cannot list A events');
with changed as (update public.cook_sessions set name='Hacked' where id='10000000-0000-4000-8000-000000000001' returning id) select pg_temp.assert_true((select count(*)=0 from changed),'B cannot modify known A cook ID');
with removed as (delete from public.cook_sessions where id='10000000-0000-4000-8000-000000000001' returning id) select pg_temp.assert_true((select count(*)=0 from removed),'B cannot delete A cook');
select pg_temp.denied($q$insert into public.cook_events(cook_id,task_id,event_type,occurred_at) values ('10000000-0000-4000-8000-000000000001','step','completed',now())$q$,'B cannot attach an event to A cook');
select pg_temp.denied($q$insert into public.cook_events(cook_id,owner_user_id,task_id,event_type,occurred_at) values ('10000000-0000-4000-8000-000000000001','00000000-0000-4000-8000-000000000001','step','completed',now())$q$,'B cannot forge event owner');
insert into public.cook_sessions(name,time_zone) values ('B private cook','UTC');
select pg_temp.assert_true((select count(*)=1 from public.cook_sessions),'B can create its own independent cook');
set local role anon;
select pg_temp.denied('select * from public.cook_sessions','anonymous cannot read cooks');
select pg_temp.denied('select * from public.cook_events','anonymous cannot read events');
select pg_temp.denied($q$insert into public.cook_sessions(name,time_zone) values ('Guest','UTC')$q$,'anonymous cannot create private cooks');
set local role authenticated;
select set_config('request.jwt.claim.sub','',true);
select pg_temp.assert_true((select count(*)=0 from public.cook_sessions),'missing JWT identity reads nothing');
select pg_temp.denied($q$insert into public.cook_sessions(name,time_zone) values ('No identity','UTC')$q$,'missing identity cannot write');
select set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000000001',true);
select pg_temp.denied($q$update public.cook_sessions set state='completed'$q$,'archive requires snapshot and finish time');
update public.cook_sessions set state='completed',finished_at=now(),completed_snapshot='{"version":1}' where revision=2;
with changed as (update public.cook_sessions set name='Rewrite archive' returning id) select pg_temp.assert_true((select count(*)=0 from changed),'completed snapshots are read-only');
select pg_temp.denied($q$insert into public.cook_events(cook_id,task_id,event_type,occurred_at) values ('10000000-0000-4000-8000-000000000001','step','reopened',now())$q$,'completed event history cannot be extended');
insert into public.cook_sessions(name,time_zone) values ('A next cook','UTC');
select pg_temp.assert_true((select count(*)=2 from public.cook_sessions),'completed history plus one new cook');
delete from public.cook_sessions where id='10000000-0000-4000-8000-000000000001';
select pg_temp.assert_true((select count(*)=0 from public.cook_events),'owner deletion cascades to owned events');
reset role;
delete from auth.users where id='00000000-0000-4000-8000-000000000002';
select pg_temp.assert_true(not exists(select 1 from public.cook_sessions where owner_user_id='00000000-0000-4000-8000-000000000002'),'account deletion removes private cooks');
rollback;
